{
  "story": "Stacking requires out-of-fold predictions to train the meta-model safely. Cross-validation splits training data into folds. Each base model predicts on left-out folds iteratively, ensuring unbiased features.",
  "aha": {
    "stateId": "fold_inference",
    "observation": "Out-of-fold predictions are generated by base models predicting exclusively on data they never saw during training."
  },
  "layout": {
    "preset": "stepper-vertical",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.step_index",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "reason": "state.why"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "values": "state.why"
      }
    },
    {
      "id": "readouts",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.step_index"
      }
    }
  ],
  "controls": [
    {
      "id": "step_index",
      "kind": "index",
      "label": "CV Step",
      "options": [
        "Split",
        "Train",
        "Predict OOF",
        "Assemble"
      ]
    },
    {
      "id": "reset_btn",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Stacking CV",
        "regions": [
          {
            "id": "fold1",
            "label": "Fold 1",
            "values": ["Validation", "Test"]
          },
          {
            "id": "fold2",
            "label": "Fold 2",
            "values": ["Train", "Train"]
          },
          {
            "id": "meta",
            "label": "Meta Feature Matrix",
            "values": ["OOF Pred 1", "OOF Pred 2"]
          }
        ],
        "states": [
          {
            "id": "split",
            "label": "Split Data",
            "sentence": "Divide training data into K distinct folds for cross-validation.",
            "why": "Prevents data leakage into the meta-learner.",
            "active": ["fold1", "fold2"],
            "calloutRegion": "fold1",
            "readouts": [
              {
                "id": "r1",
                "label": "Fold Count",
                "value": "5"
              }
            ]
          },
          {
            "id": "train",
            "label": "Train Base Model",
            "sentence": "Train base estimators on K-1 folds, holding out one fold.",
            "why": "The holdout fold remains completely unseen.",
            "active": ["fold2"],
            "calloutRegion": "fold2",
            "readouts": [
              {
                "id": "r2",
                "label": "Train Folds",
                "value": "4"
              }
            ]
          },
          {
            "id": "fold_inference",
            "label": "Predict Out-of-Fold",
            "sentence": "Generate predictions on the held-out fold using the trained model.",
            "why": "These predictions form unbiased features for the meta-model.",
            "active": ["fold1", "meta"],
            "calloutRegion": "meta",
            "readouts": [
              {
                "id": "r3",
                "label": "OOF Status",
                "value": "Unbiased"
              }
            ]
          },
          {
            "id": "assemble",
            "label": "Assemble Meta-Dataset",
            "sentence": "Concatenate all out-of-fold predictions to form the meta-training set.",
            "why": "The meta-model learns how to combine base predictions.",
            "active": ["meta"],
            "calloutRegion": "meta",
            "readouts": [
              {
                "id": "r4",
                "label": "Matrix Rows",
                "value": "N samples"
              }
            ]
          }
        ]
      }
    ]
  }
}
